import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';

import { readTable } from '../core/audio/clap-search.mjs';
import { CLAP_DIM } from '../core/audio/record.mjs';
import { GENRES } from '../core/ontology/genres.mjs';
import { prompts, TEMPLATE, DESCRIPTIONS } from '../scripts/audio-clap/prompts.mjs';

/*
 * WP-C2's build-time CLAP text table (docs/models/clap-text-table.json), held
 * to the shape WP-C3's readTable() reads and the record contract's CLAP_DIM.
 * The table is generated by scripts/audio-clap/ (prompts → text-table.py →
 * pack-table.mjs); these tests are what stop a stale or mismatched one shipping.
 */
const TABLE = new URL('../docs/models/clap-text-table.json', import.meta.url);

test('the prompt list covers every ontology genre once, then the reviewed descriptions', () => {
  const p = prompts();
  assert.equal(p.template, TEMPLATE);
  const genres = p.prompts.filter(x => x.kind === 'genre');
  assert.deepEqual(genres.map(x => x.concept).sort(), Object.keys(GENRES).sort());
  assert.equal(new Set(p.prompts.map(x => x.text)).size, p.prompts.length, 'no prompt twice');
  assert.equal(p.prompts.filter(x => x.kind === 'description').length, DESCRIPTIONS.length);
  for (const g of genres) assert.match(g.text, / music$/);
});

test('the shipped table reads, in CLAP\'s 512-d space, from the pinned music model', { skip: !existsSync(TABLE) }, () => {
  const json = JSON.parse(readFileSync(TABLE, 'utf8'));
  assert.equal(json.model, 'laion/larger_clap_music_and_speech', 'text and audio must come from one checkpoint');
  assert.equal(json.dim, CLAP_DIM);
  const t = readTable(json);
  assert.ok(t, 'readTable() must accept it');
  assert.equal(t.prompts.length, json.prompts.length, 'every prompt survives readTable');
  for (const p of t.prompts) {
    const n = Math.hypot(...p.emb);
    assert.ok(Math.abs(n - 1) < 1e-3, `${p.text} is not unit length after unpacking`);
  }
});

test('every genre in the table is one the vocabulary still has', { skip: !existsSync(TABLE) }, () => {
  const json = JSON.parse(readFileSync(TABLE, 'utf8'));
  const stale = json.prompts.filter(p => p.kind === 'genre' && !GENRES[p.concept]).map(p => p.concept);
  assert.deepEqual(stale, [], 'regenerate with scripts/audio-clap/ after removing a genre');
});

test('the text space is not collapsed, and close genres sit closer than distant ones', { skip: !existsSync(TABLE) }, () => {
  // The guard that would have caught laion/larger_clap_music: its text tower put
  // every prompt within cosine 0.999 of every other (mean vector norm 0.9996), so
  // naming and search could only ever return noise. A healthy checkpoint here
  // measures a mean genre-to-genre cosine of about 0.56.
  const t = readTable(JSON.parse(readFileSync(TABLE, 'utf8')));
  const genres = t.prompts.filter(p => p.kind === 'genre');
  const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
  let sum = 0, n = 0;
  for (let i = 0; i < genres.length; i++) for (let j = i + 1; j < genres.length; j++) { sum += dot(genres[i].emb, genres[j].emb); n++; }
  assert.ok(sum / n < 0.9, `mean genre-to-genre cosine ${(sum / n).toFixed(3)}: the text tower has collapsed`);

  const emb = c => t.prompts.find(p => p.concept === c).emb;
  const nearer = (a, near, far) => assert.ok(dot(emb(a), emb(near)) > dot(emb(a), emb(far)) + 0.1,
    `${a} should sit clearly nearer ${near} than ${far}`);
  nearer('techno', 'hard-techno', 'country');
  nearer('bassline', 'bass-house', 'country');
  nearer('house', 'deep-house', 'metal');
  nearer('metal', 'metalcore', 'house');
  nearer('hard-house', 'donk', 'jazz');
});
